const DEFAULT={weather:'cloud',moodId:'settle',emotion:'累',memory:'下雨的木头',family:'wood',need:'慢下来',intensity:'subtle',sentence:'',moodText:'',main:'天木藏香',aux:[],palette:'earth',diameter:8,wrist:16,ease:.5,accent:'single',avoid:'',lengthNote:'',form:'单圈手串',pid:'P0',quiz:0,ritual:0,result:null,paused:false,savedRoute:'quiz',selectedPhotos:[],galleryCategory:'all',galleryQuery:'',workshop:{name:'',contact:'',detail:''}};
let g={...DEFAULT,aux:[]},collection={unlocked:[],diary:[]},route='home',timer=null,breathStart=0,breathElapsed=0,breathPaused=false,toastTimer=null,sound=null,soundOn=false,planCount=0,selectedPhotos=new Set(),cardUrl='',galleryCategory='all',galleryQuery='',lastFocus=null;
const app=document.getElementById('app'),frame=document.getElementById('studio-frame');
let studioReady=false,requestSerial=0;const pending=new Map(),studioQueue=[];let studioStarted=false,storageTimer=null,lastRitualAction=0;
