const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function readStore(key,fallback){try{return JSON.parse(localStorage.getItem(key)||'null')||fallback;}catch{return fallback;}}
const cleanText=(v,max=400)=>typeof v==='string'?v.slice(0,max):'';
function sanitizeDesign(v={}){if(!v||typeof v!=='object')v={};const out={...DEFAULT,aux:[],workshop:{name:'',contact:'',detail:''},selectedPhotos:[]};
for(const k of ['moodId','family','palette','accent']){const dict={moodId:MOODS,family:SCENTS,palette:PALETTES,accent:ACCENTS}[k];if(Object.hasOwn(dict,v[k]))out[k]=v[k];}
for(const [k,max]of Object.entries({weather:30,emotion:20,memory:100,need:60,sentence:80,moodText:400,avoid:100,lengthNote:80,form:80}))out[k]=cleanText(v[k],max)||out[k];
if(['subtle','medium','full'].includes(v.intensity))out.intensity=v.intensity;
out.main=AROMAS.includes(v.main)||v.main==='交给店主配'?v.main:out.main;out.aux=[...new Set(Array.isArray(v.aux)?v.aux.filter(x=>AROMAS.includes(x)&&x!==out.main):[])].slice(0,2);
if([6,8,10,12].includes(+v.diameter))out.diameter=+v.diameter;out.wrist=Number.isFinite(+v.wrist)?Math.min(23,Math.max(12,+v.wrist)):16;out.ease=[.5,1,1.5].includes(+v.ease)?+v.ease:.5;
out.quiz=Number.isInteger(v.quiz)?Math.max(0,Math.min(5,v.quiz)):0;out.ritual=Number.isInteger(v.ritual)?Math.max(0,Math.min(4,v.ritual)):0;out.paused=v.paused===true;
if(PHOTOS.some(p=>p.pid===v.pid))out.pid=v.pid;out.savedRoute=JOURNEY_ROUTES.includes(v.savedRoute)?v.savedRoute:'quiz';
out.selectedPhotos=[...new Set(Array.isArray(v.selectedPhotos)?v.selectedPhotos.filter(id=>PHOTOS.some(p=>p.pid===id)):[])];out.galleryCategory=['all','手串','项链','香牌'].includes(v.galleryCategory)?v.galleryCategory:'all';out.galleryQuery=cleanText(v.galleryQuery,100);
for(const [k,max]of Object.entries({name:50,contact:100,detail:500}))out.workshop[k]=cleanText(v.workshop?.[k],max);return out;}
function sanitizeResult(v){if(!v||typeof v!=='object'||typeof v.id!=='string'||!/^[A-Za-z0-9-]{3,70}$/.test(v.id)||!Object.hasOwn(MOODS,v.moodId))return null;const d=sanitizeDesign(v);delete d.workshop;delete d.selectedPhotos;return {...d,result:undefined,id:v.id,name:cleanText(v.name,40)||MOODS[d.moodId].name+'，有香',date:cleanText(v.date,20)||dateText(),hidden:cleanText(v.hidden,40)||null};}
function load(){craftTransfer=window.XYCraft?.normalize(readStore(CRAFT_KEY,null))||null;const d=readStore(PLAY_KEY,null);if(d?.version===1&&d.data){g=sanitizeDesign(d.data);g.result=sanitizeResult(d.data.result);if(g.result&&!d.data.savedRoute)g.savedRoute='result';}
const c=readStore(COLLECTION_KEY,null);if(c&&Array.isArray(c.unlocked)&&Array.isArray(c.diary))collection={unlocked:[...new Set(c.unlocked.filter(x=>AROMAS.includes(x)))],diary:c.diary.map(sanitizeResult).filter(Boolean).slice(0,50)};
selectedPhotos=new Set(g.selectedPhotos);galleryCategory=g.galleryCategory;galleryQuery=g.galleryQuery;document.body.classList.toggle('paused',!!g.paused);
const draft=readStore('xiangyu-play-multi-proposal-v2',null)||readStore('xiangyu-owner-multi-proposal-v1',null);const st=draft?.state;if(Array.isArray(st?.lines))planCount=st.mode==='mix'?(Number(st.mixQuantity)||0):st.lines.reduce((n,l)=>n+(Number(l.quantity)||0),0);document.getElementById('plan-badge').textContent='我的方案'+(planCount?' · '+planCount:'');}
function flushStore(){clearTimeout(storageTimer);try{localStorage.setItem(PLAY_KEY,JSON.stringify({version:1,data:g}));localStorage.setItem(COLLECTION_KEY,JSON.stringify(collection));}catch{toast('当前浏览器未保存，请下载或复制方案。');}}
function persist(immediate=true){g.selectedPhotos=[...selectedPhotos];g.galleryCategory=galleryCategory;g.galleryQuery=galleryQuery;if(JOURNEY_ROUTES.includes(route))g.savedRoute=route;if(immediate)flushStore();else{clearTimeout(storageTimer);storageTimer=setTimeout(flushStore,250);}}
addEventListener('pagehide',flushStore);
function eventName(name){document.dispatchEvent(new CustomEvent('xiangyu:local-event',{detail:{name}}));} // No external analytics.
function toast(t){const el=document.getElementById('toast');el.textContent=t;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,3600);}
function dateText(d=new Date()){return d.getFullYear()+'.'+String(d.getMonth()+1).padStart(2,'0')+'.'+String(d.getDate()).padStart(2,'0');}
function progress(n,max=4){return '<div class="progress" aria-label="进度 '+n+'/'+max+'">'+Array.from({length:max},(_,i)=>'<i class="'+(i<n?'done':'')+'"></i>').join('')+'</div>';}
function stepTop(back,n,max=4){return '<div class="backrow"><button class="back" data-route="'+back+'">← 返回</button>'+progress(n,max)+'</div>';}
function btn(text,action,kind='blue'){return '<button type="button" class="btn '+kind+'" data-action="'+action+'">'+text+'</button>';}
function foot(note='香方与适配由店主确认。'){return '<p class="tiny" style="margin-top:18px">'+note+'</p>';}
function size(c=g){const diameter=+c.diameter,wrist=+c.wrist,ease=+c.ease,accentCount=c.accent==='none'?0:1,accentSize=c.accent==='metal'?4:diameter;const mainCount=Math.max(5,Math.round(((wrist+ease)*10+Math.PI*diameter-accentCount*accentSize)/diameter));return {mainCount,inner:+((mainCount*diameter+accentCount*accentSize-Math.PI*diameter)/10).toFixed(1)};}
function diagram(c=g,large=false){const colors=PALETTES[c.palette]||PALETTES.earth,{mainCount}=size(c),n=mainCount+(c.accent==='none'?0:1),r=87,dot=Math.min(15,Math.PI*r/n*.83);let out='<svg class="preview-circle" viewBox="0 0 330 250" role="img" aria-label="数字珠圈设计示意，非商品实拍"><defs><radialGradient id="bead-shade"><stop stop-color="'+colors.main+'" offset="0"/><stop stop-color="#202421" stop-opacity=".78" offset="1"/></radialGradient></defs><circle cx="165" cy="123" r="87" fill="none" stroke="#929b8b" stroke-dasharray="2 6"/>';
for(let i=0;i<n;i++){const a=i/n*Math.PI*2-Math.PI/2,x=165+Math.cos(a)*r,y=123+Math.sin(a)*r,accent=c.accent!=='none'&&i===0;out+='<circle cx="'+x.toFixed(2)+'" cy="'+y.toFixed(2)+'" r="'+(accent&&c.accent==='metal'?7:dot)+'" fill="'+(accent?(c.accent==='metal'?'#bc984e':colors.accent):'url(#bead-shade)')+'" stroke="#202421" stroke-width=".5"/>';}
return out+'<text x="165" y="123" text-anchor="middle" font-size="27" fill="#202421" font-family="serif">'+esc(MOODS[c.moodId||g.moodId].name)+'</text><text x="165" y="148" text-anchor="middle" font-size="11" fill="#626961">'+c.diameter+' mm · '+mainCount+'颗主珠</text></svg>';}
function chosenMain(){const map={wood:['天木藏香','紫气东来','归元'],fresh:['鹅梨','蓝色妖姬','芳华'],floral:['桂花','茉莉','花蕊夫人'],herbal:['药香','苏合','五行']};return map[g.family]||map.wood;}
function photoCard(p,mode='reference'){const on=mode==='reference'?p.pid===g.pid:selectedPhotos.has(p.pid);return '<article class="photo-card '+(on?'selected':'')+'"><button class="photo-zoom" data-photo-viewer aria-label="放大查看：'+esc(p.name)+'"><img src="'+esc(p.img)+'" alt="'+esc(p.name)+'，原款实拍" loading="lazy" decoding="async" width="360" height="270"></button><h3>'+esc(p.name)+'</h3><p>'+esc(p.pid)+' / #'+p.srcIdx+' · '+esc(p.cat)+'</p><button data-'+(mode==='reference'?'reference':'product')+'="'+esc(p.pid)+'" aria-pressed="'+on+'">'+(on?'✓ 已选为'+(mode==='reference'?'参考':'意向'):(mode==='reference'?'选作实拍参考':'选入购买意向'))+'</button></article>';}
