const oldRoute=app.dataset.route;const focused=document.activeElement;const focusAttr=focused?.getAttributeNames?.().find(k=>k.startsWith('data-')&&!['data-route','data-action'].includes(k));const focusValue=focusAttr?focused.getAttribute(focusAttr):null;window.XYMotion?.before();clearInterval(timer);timer=null;document.getElementById('studio-container').hidden=route!=='plan';app.hidden=route==='plan';document.querySelectorAll('.footer-nav [data-route]').forEach(b=>b.setAttribute('aria-current',b.dataset.route===route?'page':'false'));document.getElementById('motion-toggle').setAttribute('aria-pressed',String(g.paused));document.getElementById('motion-toggle').textContent=g.paused?'已停':'动态';
